import { TemplateView } from './TemplateView';
import { IStatus } from './StatusManager';
import StoreManager from '../../store/StoreManager';

import { AUTOSPINSTATUSMAP, GAMESTOREMAP } from '../../store/StoreMap';
import { UIOpacity, Vec3 } from 'cc';
export default class NewGameStatus implements IStatus {
    templateView: TemplateView;
    storeManager: StoreManager;

    /**
     * 注入所屬的操作列與 StoreManager。
     *
     * @param context 這個狀態要操作的操作列。
     * @returns 自己，方便串接呼叫。
     */
    setContext(context: TemplateView) {
        this.templateView = context;
        this.storeManager = StoreManager.getInstance();

        return this;
    }
    /**
     * 進入「可以開始新一局」狀態：清掉上一局的局號、解鎖注額按鈕，
     * 並依自動轉狀態決定要繼續轉還是停下來。
     */
    onEnter() {
        this.storeManager.getGameStore().setRoundId(null);
        this.templateView.refreshBetButtons(false);
        this.storeManager.getGameStore().setIsLock(false);
        if (this.storeManager.getGameStore().autoSpinStatus === AUTOSPINSTATUSMAP.ON && !this.storeManager.getGameStore().spinCheck()) this.storeManager.getGameStore().setAutoSpinStatus(AUTOSPINSTATUSMAP.OFF);

        if (this.storeManager.getGameStore().autoSpinStatus === AUTOSPINSTATUSMAP.ON) {
            //減少AutoSpin 數字
            let currentTimes = this.storeManager.getGameStore().autoSpinTimes;
            if (currentTimes === 'MAX') {
                this.templateView.setInfiniteVisible(true);
                this.doNextSpin();
            } else if (currentTimes > 0) {
                // 不在這裡遞減 autoSpinTimes：直橫版各跑一次 onEnter，扣兩次會少一局
                this.doNextSpin();
            } else {
                this.storeManager.getGameStore().setAutoSpinStatus(AUTOSPINSTATUSMAP.OFF);
                this.templateView.setDefaultMode();
            }
            return;
        }
        this.templateView.setDefaultMode();
    }

    /** setSpinStatus。 */
    private doNextSpin(): void {
        setTimeout(() => this.storeManager.getGameStore().setSpinStatus(GAMESTOREMAP.SPIN_START), 0);
    }
    /**
     * 離開狀態，不需要收尾。
     */
    onExit() {}
}
