function multiplierValueOf(id: number): number {
    const idx = id >= UPGRADEABLE_SYMBOL_MIN ? id - UPGRADEABLE_SYMBOL_MIN : id - MULTIPLIER_SYMBOL_MIN;
    return MULTIPLIER_VALUES[idx] ?? 0;
}
function isMultiplierId(id: number): boolean {
    return (id >= MULTIPLIER_SYMBOL_MIN && id <= MULTIPLIER_SYMBOL_MAX) || (id >= UPGRADEABLE_SYMBOL_MIN && id <= UPGRADEABLE_SYMBOL_MAX);
}

/** Mock Jackpot 派獎倍率 */
const DEBUG_JACKPOT_PAYOUT_MUL: Record<SlotApiJackpotTier, number> = { MINI: 5, MINOR: 20, MAJOR: 100, GRAND: 500 };

/** JP 數量對應 tier 2=MINI 3=MINOR 4=MAJOR 5=GRAND */
