const JACKPOT_COUNT_TIER: Partial<Record<number, SlotApiJackpotTier>> = { 2: 'MINI', 3: 'MINOR', 4: 'MAJOR', 5: 'GRAND' };
const JACKPOT_NATURAL_CHANCE = 0.05;

/** 1001 Mock Jackpot */
function decideJackpotSymbolCount(): number {
    const jackpot = getSlotApiDebugControl()?.jackpot;
    const forcedTier = (['grand', 'major', 'minor', 'mini'] as const).find((key) => jackpot?.[key])?.toUpperCase() as SlotApiJackpotTier | undefined;
    if (forcedTier) return JACKPOT_TIER_SYMBOL_COUNT[forcedTier];
    if (Math.random() >= JACKPOT_NATURAL_CHANCE) return 0;
    return 1 + Math.floor(Math.random() * 5);
}

function makeJackpotResult(betAmount: string, count: number): SlotApiJackpotSpinResult {
    const tier = JACKPOT_COUNT_TIER[count];
    if (!tier) return { won: false, tier: '', payout: '0', currency: state.currency };
    const payout = (Number(betAmount) || 0) * DEBUG_JACKPOT_PAYOUT_MUL[tier];
    return { won: true, tier, payout: amount(payout), currency: state.currency };
}

function pickDistinctGridPositions(cols: number, rows: number, count: number): [number, number][] {
    const all: [number, number][] = [];
    for (let col = 0; col < cols; col++) for (let row = 0; row < rows; row++) all.push([col, row]);
    for (let i = all.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [all[i], all[j]] = [all[j], all[i]];
    }
    return all.slice(0, Math.min(count, all.length));
}

type JackpotSpot = { col: number; row: number; from_symbol_id: number };

function stampJackpot(cells: number[][], positions: [number, number][]): JackpotSpot[] {
    return positions.map(([col, row]) => {
        const from_symbol_id = cells[col][row];
        cells[col][row] = JACKPOT_SYMBOL_ID;
        return { col, row, from_symbol_id };
    });
}

function toTerminalReplacements(spots: JackpotSpot[]): SlotApiRoundResult['presentation']['main']['terminal_replacements'] {
    return spots.map((s) => ({
        reason: 'jackpot',
        position: { col: s.col, row: s.row },
        from_symbol_id: s.from_symbol_id,
        to_symbol_id: JACKPOT_SYMBOL_ID,
    }));
}

