function randomNormalSymbol(excludeSymbolId?: number): number {
    const symbol = NORMAL_SYMBOL_MIN + randomInt(NORMAL_SYMBOL_MAX - NORMAL_SYMBOL_MIN + 1);
    return symbol === excludeSymbolId ? (symbol % NORMAL_SYMBOL_MAX) + NORMAL_SYMBOL_MIN : symbol;
}

function makeGrid(excludeSymbolId?: number): number[][] {
    return Array.from({ length: MOCK_LAYOUT.columns }, () =>
        Array.from({ length: MOCK_LAYOUT.visibleRows }, () => {
            return randomNormalSymbol(excludeSymbolId);
        })
    );
}

function tierOdds(symbolId: number, count: number): number {
    const tiers = PAY_TABLE_DATA[symbolId] ?? [];
    let odds = 0;
    for (const [minCount, tierOddsValue] of tiers) {
        if (count >= minCount) odds = Number(tierOddsValue);
    }
    return odds;
}

function placeSymbols(cells: number[][], positions: number[][], symbolId: number): void {
    for (const [col, row] of positions) cells[col][row] = symbolId;
}

/**
 * 檢查盤面符號 補完重新判斷到乾淨為止
 * scatter(10)/倍率球 不參與這個判斷 沒做 */
function evaluateWins(cells: number[][], betAmount: string): SlotApiAward[] {
    const bySymbol = new Map<number, number[][]>();
    for (let col = 0; col < MOCK_LAYOUT.columns; col++) {
        for (let row = 0; row < MOCK_LAYOUT.visibleRows; row++) {
            const id = cells[col][row];
            if (id < NORMAL_SYMBOL_MIN || id > NORMAL_SYMBOL_MAX) continue;
            (bySymbol.get(id) ?? bySymbol.set(id, []).get(id)!).push([col, row]);
        }
    }
    const awards: SlotApiAward[] = [];
    for (const [id, positions] of bySymbol) {
        const odds = tierOdds(id, positions.length);
        if (odds <= 0) continue;
        const pay = (Number(betAmount) / COINS) * odds;
        awards.push({ SymbolID: id, Count: positions.length, Positions: positions, Pay: amount(pay) });
    }
    return awards;
}

const MUL_TIER_WEIGHTS: [number, number][] = [
    [0, 0.3],
    [5, 0.25],
    [10, 0.2],
    [15, 0.25],
];
function randomMultiplierIdx(): number {
    let r = Math.random();
    for (const [base, weight] of MUL_TIER_WEIGHTS) {
        if (r < weight) return base + randomInt(5);
        r -= weight;
    }
    return 15 + randomInt(5);
}

function placeMultipliers(cells: number[][], positions: number[][], cursor: number): void {
    const multiplierCount = randomInt(MAX_MULTIPLIERS + 1);
    for (let i = 0; i < multiplierCount; i++) {
        const position = positions[cursor + i];
        if (!position) return;
        const [col, row] = position;
        cells[col][row] = UPGRADEABLE_SYMBOL_MIN + randomMultiplierIdx();
    }
}

function makeStep(betAmount: string, mode: 'normal' | 'scatter' | 'empty', forcedSymbol?: { symbol: number; count: number }): SlotApiStep {
    const positions = shuffle(allPositions());
    const normalSymbolId = forcedSymbol?.symbol ?? randomNormalSymbol();
    const cells = makeGrid(mode === 'empty' ? undefined : normalSymbolId);

    if (mode === 'empty') {
        placeMultipliers(cells, positions, 0);
        return {
            Grid: { Cols: MOCK_LAYOUT.columns, Rows: MOCK_LAYOUT.visibleRows, Cells: cells },
            Awards: [],
            Win: '0',
        };
    }

    let cursor = 0;
    let stepWin = 0;
    const awards: SlotApiAward[] = [];

    if (mode === 'scatter') {
        const scatterCount = 4;
        const scatterPositions = positions.slice(cursor, cursor + scatterCount);
        cursor += scatterCount;
        placeSymbols(cells, scatterPositions, SCATTER_SYMBOL_ID);
        const scatterWin = (Number(betAmount) / COINS) * tierOdds(SCATTER_SYMBOL_ID, scatterCount);
        stepWin += scatterWin;
        awards.push({
            SymbolID: SCATTER_SYMBOL_ID,
            Count: scatterCount,
            Positions: scatterPositions,
            Pay: amount(scatterWin),
        });
    }

    const countOptions = [8, 10, 12];
    const count = forcedSymbol?.count ?? countOptions[randomInt(countOptions.length)];
    const awardPositions = positions.slice(cursor, cursor + count);
    cursor += count;
    placeSymbols(cells, awardPositions, normalSymbolId);

    const normalWin = (Number(betAmount) / COINS) * tierOdds(normalSymbolId, count);
    stepWin += normalWin;
    awards.push({
        SymbolID: normalSymbolId,
        Count: count,
        Positions: awardPositions,
        Pay: amount(normalWin),
    });

    placeMultipliers(cells, positions, cursor);

    return {
        Grid: { Cols: MOCK_LAYOUT.columns, Rows: MOCK_LAYOUT.visibleRows, Cells: cells },
        Awards: awards,
        Win: amount(stepWin),
    };
}

function sumStepWins(steps: SlotApiStep[]): number {
    return steps.reduce((sum, step) => sum + Number(step.Win || 0), 0);
}

function makeTransitions(steps: SlotApiStep[]): SlotApiTransition[] {
    return steps.slice(0, -1).map((step, fromStep) => {
        const next = steps[fromStep + 1];
        const eliminatedIds = new Set((step.Awards ?? []).map((award) => Number(award.SymbolID)).filter((id) => id !== SCATTER_SYMBOL_ID));
        const cleared = (step.Awards ?? [])
            .filter((award) => eliminatedIds.has(Number(award.SymbolID)))
            .flatMap((award) => award.Positions.map(([col, row]) => ({ symbol_id: Number(award.SymbolID), position: { col, row } })));
        const moved: SlotApiTransition['moved'] = [];
        const upgraded: SlotApiTransition['upgraded'] = [];
        const spawned: SlotApiTransition['spawned'] = [];

        step.Grid.Cells.forEach((column, col) => {
            const survivors = column.map((symbolId, row) => ({ symbolId, row })).filter(({ symbolId }) => !eliminatedIds.has(symbolId));
            const fillCount = MOCK_LAYOUT.visibleRows - survivors.length;
            for (let row = 0; row < fillCount; row++) spawned.push({ symbol_id: next.Grid.Cells[col][row], position: { col, row } });
            survivors.forEach(({ symbolId, row }, index) => {
                const targetRow = fillCount + index;
                const targetSymbolId = next.Grid.Cells[col][targetRow];
                if (row !== targetRow) moved.push({ symbol_id: symbolId, from: { col, row }, to: { col, row: targetRow } });
                if (symbolId !== targetSymbolId) {
                    upgraded.push({
                        position: { col, row: targetRow },
                        from_symbol_id: symbolId,
                        to_symbol_id: targetSymbolId,
                        from_multiplier: multiplierValueOf(symbolId),
                        to_multiplier: multiplierValueOf(targetSymbolId),
                    });
                }
            });
        });

        return { from_step: fromStep, to_step: fromStep + 1, cleared, moved, upgraded, spawned };
    });
}

function settleStep(prevStep: SlotApiStep, betAmount: string): SlotApiStep {
    const elimIds = new Set<number>();
    for (const award of prevStep.Awards ?? []) {
        const symbolId = Number(award.SymbolID);
        if (symbolId !== SCATTER_SYMBOL_ID) elimIds.add(symbolId);
    }
    const cells = prevStep.Grid.Cells.map((colCells) => {
        const survivors = colCells.filter((id) => !elimIds.has(id)).map((id) => (id >= UPGRADEABLE_SYMBOL_MIN && id < UPGRADEABLE_SYMBOL_MAX ? id + 1 : id));
        const fillCount = MOCK_LAYOUT.visibleRows - survivors.length;
        const fills = Array.from({ length: fillCount }, () => randomNormalSymbol());
        // 新符號從上方補入
        return [...fills, ...survivors];
    });
    const awards = evaluateWins(cells, betAmount);
    const win = awards.reduce((s, a) => s + Number(a.Pay), 0);
    return { Grid: { Cols: MOCK_LAYOUT.columns, Rows: MOCK_LAYOUT.visibleRows, Cells: cells }, Awards: awards, Win: amount(win) };
}

function sumMultipliers(step: SlotApiStep): number {
    let sum = 0;
    for (const colCells of step.Grid.Cells) {
        for (const id of colCells) {
            if (isMultiplierId(id)) sum += multiplierValueOf(id);
        }
    }
    return sum;
}

/** JP 只寫入 terminal Grid */
function makeRoundResult(betAmount: string, buyFeature: boolean, jackpotCount: number): { roundResult: SlotApiRoundResult; totalWin: number; multiplier: number; actualJackpotCount: number } {
    // Debug 設定優先
    const debugControl = getSlotApiDebugControl();
    const forcedSymbol = debugControl?.symbol_control;
    const hasAnyDebugControl = !!(forcedSymbol || debugControl?.win || (debugControl?.jackpot && Object.values(debugControl.jackpot).some(Boolean)));
    const triggerFree = buyFeature || (!hasAnyDebugControl && Math.random() < 0.25);
    const mainMode = triggerFree ? 'scatter' : forcedSymbol ? 'normal' : Math.random() < 0.82 ? 'normal' : 'empty';
    const mainWinStep = makeStep(betAmount, mainMode, forcedSymbol);

    let jackpotSpots: JackpotSpot[] = [];
    let main: SlotApiStep[];

    if (triggerFree) {
        main = [{ ...mainWinStep, Awards: [], Win: '0' }];
    } else if (mainMode === 'empty') {
        // 沒有一般中獎 Awards 直接省略
        if (jackpotCount > 0) jackpotSpots = stampJackpot(mainWinStep.Grid.Cells, pickDistinctGridPositions(MOCK_LAYOUT.columns, MOCK_LAYOUT.visibleRows, jackpotCount));
        main = [mainWinStep];
    } else {
        // 先跑掉落 cascade
        main = [mainWinStep];
        while ((main[main.length - 1].Awards?.length ?? 0) > 0 && main.length < MAX_CASCADE_STEPS) {
            main.push(settleStep(main[main.length - 1], betAmount));
        }

        if (jackpotCount > 0) {
            const terminal = main[main.length - 1];
            jackpotSpots = stampJackpot(terminal.Grid.Cells, pickDistinctGridPositions(MOCK_LAYOUT.columns, MOCK_LAYOUT.visibleRows, jackpotCount));
        }
    }

    const free: SlotApiStep[][] = [];
    const freeMultipliers: MockFreeMultiplier[] = [];

    if (triggerFree) {
        const freeRounds = 15;
        let acc = 0;
        for (let i = 0; i < freeRounds; i++) {
            const fMode = forcedSymbol ? 'normal' : Math.random() < 0.7 ? 'normal' : 'empty';
            const fStep = makeStep(betAmount, fMode, forcedSymbol);
            // 同樣補出乾淨為止
            const steps: SlotApiStep[] = [fStep];
            while ((steps[steps.length - 1].Awards?.length ?? 0) > 0 && steps.length < MAX_CASCADE_STEPS) {
                steps.push(settleStep(steps[steps.length - 1], betAmount));
            }
            free.push(steps);
            const rawWin = sumStepWins(steps);
            const mult = sumMultipliers(steps[steps.length - 1]);
            let win = rawWin;
            if (rawWin > 0 && mult > 0) {
                acc += mult;
                win = rawWin * acc;
            }
            freeMultipliers.push({ round: i, mult, acc, win: amount(win) });
        }
    }

    const mainWin = sumStepWins(main);
    const multiplier = !triggerFree && mainWin > 0 ? sumMultipliers(main[main.length - 1]) : 0;
    const freeWin = freeMultipliers.reduce((sum, fm) => sum + (Number(fm.win) || 0), 0);
    const mainPaid = multiplier > 0 ? mainWin * multiplier : mainWin;
    let totalWin = mainPaid + freeWin;

    // Debug 贏分只覆寫 total_win
    const forcedWin = debugControl?.win;
    if (forcedWin) {
        const bet = Number(betAmount) || 0;
        const forcedMultiplier = forcedWin.min + Math.random() * (forcedWin.max - forcedWin.min);
        totalWin = bet * forcedMultiplier;
    }

    const actualJackpotCount = jackpotSpots.length;
    return {
        totalWin,
        multiplier,
        actualJackpotCount,
        roundResult: {
            schema_version: 'slot.round_result.v1',
            Main: main,
            Free: triggerFree ? free : [],
            TotalWin: amount(totalWin),
            RNGUsed: [],
            Multiplier: multiplier,
            FreeGameTriggered: triggerFree,
            FreeMultipliers: triggerFree ? freeMultipliers : [],
            JackpotTier: actualJackpotCount,
            JackpotCount: actualJackpotCount,
            presentation: {
                version: 'slot.presentation.v1',
                coordinate_space: { origin: 'top_left', columns: MOCK_LAYOUT.columns, rows: MOCK_LAYOUT.visibleRows },
                main: { transitions: makeTransitions(main), terminal_replacements: toTerminalReplacements(jackpotSpots) },
                free_rounds: free.map((steps, roundIndex) => ({
                    round_index: roundIndex,
                    transitions: makeTransitions(steps),
                    multiplier: {
                        round_multiplier: freeMultipliers[roundIndex].mult,
                        accumulated_before: roundIndex > 0 ? freeMultipliers[roundIndex - 1].acc : 0,
                        accumulated_after: freeMultipliers[roundIndex].acc,
                        win: freeMultipliers[roundIndex].win,
                    },
                    retrigger: { triggered: false, awarded_rounds: 0, total_rounds_after: free.length },
                })),
            },
        },
    };
}

function response<T>(type: SlotApiFrame<T>['type'], correlationId: string | undefined, payload: T): SlotApiFrame<T> {
    return { type, correlation_id: correlationId, payload };
}

function ack(correlationId: string | undefined, code: string, message: string): SlotApiFrame {
    return { type: SLOT_API_RESPONSE_TYPE.ACK, correlation_id: correlationId, error: { code, message } };
}

function sendFrame(socket: SlotApiMockWebSocket, frame: SlotApiFrame, delay: number = LATENCY_MS): void {
    setTimeout(() => socket.receive(frame), delay);
}

function handleSpin(socket: SlotApiMockWebSocket, frame: SlotApiFrame): void {
    const payload = frame.payload as SlotApiSpinRequest;
    const correlationId = frame.correlation_id;
    if (correlationId && state.completedSpins.has(correlationId)) {
        sendFrame(socket, state.completedSpins.get(correlationId)!);
        return;
    }
    if (correlationId && state.pendingSpins.has(correlationId)) {
        sendFrame(socket, ack(correlationId, 'SLOT_SPIN_FAILED', 'spin_in_progress'));
        return;
    }

    const betConfig = getBetConfig(state.currency)!;
    const betAmount = String(payload.bet_amount ?? '');
    if (!betConfig.levels.includes(betAmount)) {
        sendFrame(socket, ack(correlationId, 'SLOT_SPIN_FAILED', `bet_out_of_range: ${betAmount}`));
        return;
    }

    if (correlationId) state.pendingSpins.add(correlationId);
    const buyFeature = payload.buy_feature === true;
    const cost = Number(betAmount) * (buyFeature ? BUY_FEATURE_COST_MUL : 1);

    // 多階同時選取時優先最高 tier
    const jackpotSymbolCount = decideJackpotSymbolCount();
    const { roundResult, totalWin: baseTotalWin, actualJackpotCount } = makeRoundResult(betAmount, buyFeature, jackpotSymbolCount);
    const jackpotResult = makeJackpotResult(betAmount, actualJackpotCount);
    const totalWin = baseTotalWin + Number(jackpotResult.payout);
    roundResult.TotalWin = amount(totalWin);
    if (jackpotResult.won) {
        console.log('[Mock][Debug] 強制 Jackpot', { tier: jackpotResult.tier, payout: jackpotResult.payout, baseTotalWin, totalWin });
    }

    state.balance = Math.max(0, state.balance - cost + totalWin);
    state.nextBetId = (BigInt(state.nextBetId) + BigInt(1)).toString();
    const betId = state.nextBetId;
    const payloadResponse: SlotApiSpinResponse = {
        bet_id: betId,
        operation_id: betId,
        total_win: amount(totalWin),
        raw_engine_win: amount(baseTotalWin),
        engine_win: amount(baseTotalWin),
        max_win: { applied: false, multiplier: '', cap_amount: '' },
        multiplier: roundResult.Multiplier,
        free_game_triggered: roundResult.FreeGameTriggered,
        outcome: totalWin > 0 ? 'won' : 'lost',
        balance_after: amount(state.balance),
        free_round: false,
        charged_wager: amount(cost),
        round_result: roundResult,
        jackpot: jackpotResult,
    };
    const frameResponse = response(SLOT_API_RESPONSE_TYPE.SLOT_SPIN_RESPONSE, correlationId, payloadResponse);
    const summary: SlotApiBetHistoryItem = {
        operation_id: betId,
        game_code: 'sethg',
        currency: state.currency,
        bet_amount: betAmount,
        win_amount: amount(totalWin),
        raw_engine_win: amount(baseTotalWin),
        engine_win: amount(baseTotalWin),
        profit: amount(totalWin - cost),
        created_at_ms: Date.now(),
        balance_after: payloadResponse.balance_after,
        buy_feature: buyFeature,
        is_free_round: false,
        ...(jackpotResult.won ? { jackpot_payout: jackpotResult.payout } : {}),
    };
    state.history.unshift({ summary, roundResult });
    if (state.history.length > MAX_HISTORY_ITEMS) state.history.length = MAX_HISTORY_ITEMS;
    if (correlationId) {
        state.completedSpins.set(correlationId, frameResponse);
        if (state.completedSpins.size > MAX_COMPLETED_SPINS) {
            const oldestKey = state.completedSpins.keys().next().value;
            if (oldestKey !== undefined) state.completedSpins.delete(oldestKey);
        }
    }
    setTimeout(() => {
        if (correlationId) state.pendingSpins.delete(correlationId);
        socket.receive(frameResponse);
    }, LATENCY_MS);
}

function handleFrame(socket: SlotApiMockWebSocket, frame: SlotApiFrame): void {
    switch (frame.type) {
        case 'PING':
            sendFrame(socket, response(SLOT_API_RESPONSE_TYPE.PONG, frame.correlation_id, undefined));
            return;
        case 'SLOT_GET_GAME': {
            const payload = (frame.payload ?? {}) as SlotApiGetGameRequest;
            const gameData = makeGetGameResponse(state.currency);
            if (!gameData) {
                sendFrame(socket, ack(frame.correlation_id, 'SLOT_GET_GAME_FAILED', 'currency_not_configured'));
                return;
            }
            sendFrame(socket, response(SLOT_API_RESPONSE_TYPE.SLOT_GET_GAME_RESPONSE, frame.correlation_id, gameData));
            return;
        }
        case 'GET_GAME_INFO': {
            const payload = (frame.payload ?? {}) as { currency?: string };
            const info = makeGameInfo(payload.currency || state.currency);
            if (!info) {
                sendFrame(socket, ack(frame.correlation_id, 'GET_GAME_INFO_FAILED', 'currency_not_configured'));
                return;
            }
            state.currency = payload.currency || state.currency;
            sendFrame(socket, response(SLOT_API_RESPONSE_TYPE.GET_GAME_INFO_RESPONSE, frame.correlation_id, info));
            return;
        }
        case 'SLOT_SPIN':
            handleSpin(socket, frame);
            return;
        case 'GET_GAME_STATE': {
            const bet = getBetConfig(state.currency)!;
            const last = state.history[0];
            const slot_state: SlotApiGameStateResponse['slot_state'] = {
                min_bet: bet.min,
                max_bet: bet.max,
                default_bet: bet.defaultBet,
                bet_levels: bet.levels,
                game_active: true,
                spin_allowed: true,
            };
            if (last) {
                const summary = last.summary;
                slot_state.last_spin = {
                    operation_id: summary.operation_id,
                    bet_amount: summary.bet_amount,
                    total_win: summary.win_amount,
                    outcome: Number(summary.win_amount) > 0 ? 'won' : 'lost',
                    balance_after: summary.balance_after,
                };
            }
            sendFrame(
                socket,
                response(SLOT_API_RESPONSE_TYPE.GET_GAME_STATE_RESPONSE, frame.correlation_id, {
                    currency: state.currency,
                    balance: amount(state.balance),
                    slot_state,
                })
            );
            return;
        }
        case 'GET_BET_HISTORY': {
            const request = frame.payload as SlotApiBetHistoryRequest;
            const limit = Math.min(Math.max(request.limit, 1), 100);
            let startIndex = 0;
            if (request.cursor) {
                const operationId = request.cursor.startsWith('mock:') ? request.cursor.slice(5) : '';
                const foundIndex = state.history.findIndex((item) => item.summary.operation_id === operationId);
                if (foundIndex === -1) {
                    // cursor 已不在
            sendFrame(socket, response(SLOT_API_RESPONSE_TYPE.GET_BET_HISTORY_RESPONSE, frame.correlation_id, { items: [] }));
                    return;
                }
                startIndex = foundIndex + 1;
            }
            const page = state.history.slice(startIndex, startIndex + limit);
            const items: SlotApiBetHistoryItem[] = page.map(({ summary }) => ({ ...summary }));
            const hasMore = startIndex + limit < state.history.length;
            const historyResponse: SlotApiBetHistoryResponse = items.length > 0 ? { items, ...(hasMore ? { has_more: true, next_cursor: `mock:${items[items.length - 1].operation_id}` } : {}) } : { items: [] };
            sendFrame(socket, response(SLOT_API_RESPONSE_TYPE.GET_BET_HISTORY_RESPONSE, frame.correlation_id, historyResponse));
            return;
        }
        case 'GET_BET_DETAIL': {
            const request = frame.payload as SlotApiBetDetailRequest;
            const detail = state.history.find((item) => item.summary.operation_id === request.operation_id);
            if (!detail) {
                sendFrame(socket, ack(frame.correlation_id, 'GET_BET_DETAIL_FAILED', 'bet_not_found'));
                return;
            }
            const detailResponse: SlotApiBetDetailResponse = {
                engine_win: detail.summary.engine_win,
                raw_engine_win: detail.summary.raw_engine_win,
                rng_used_json: '[]',
                round_result: detail.roundResult,
                summary: detail.summary,
            };
            sendFrame(socket, response(SLOT_API_RESPONSE_TYPE.GET_BET_DETAIL_RESPONSE, frame.correlation_id, detailResponse));
            return;
        }
        case 'GET_JACKPOT_POOL':
        case 'SUBSCRIBE_JACKPOT_POOL': {
            const request = frame.payload as SlotApiJackpotPoolRequest;
            const responseType = frame.type === 'GET_JACKPOT_POOL' ? SLOT_API_RESPONSE_TYPE.GET_JACKPOT_POOL_RESPONSE : SLOT_API_RESPONSE_TYPE.SUBSCRIBE_JACKPOT_POOL_RESPONSE;
            sendFrame(socket, response(responseType, frame.correlation_id, fakeJackpotPoolSnapshot(request.game_code)));
            if (frame.type === 'SUBSCRIBE_JACKPOT_POOL') {
                if (socket.jackpotPoolInterval !== null) clearInterval(socket.jackpotPoolInterval);
                socket.jackpotPoolInterval = setInterval(() => {
                    bumpJackpotPools();
                    // 主動推播跟單次查詢共用
                    sendFrame(socket, response(SLOT_API_RESPONSE_TYPE.JACKPOT_POOL_UPDATE, undefined, fakeJackpotPoolSnapshot(request.game_code)), 0);
                }, JACKPOT_POOL_REPAIR_TICK * 1000);
            }
            return;
        }
        case 'UNSUBSCRIBE_JACKPOT_POOL': {
            const request = frame.payload as SlotApiJackpotPoolRequest;
            if (socket.jackpotPoolInterval !== null) {
                clearInterval(socket.jackpotPoolInterval);
                socket.jackpotPoolInterval = null;
            }
            const unsubResponse: SlotApiJackpotUnsubscribeResponse = { game_code: request.game_code, currency: state.currency, subscribed: false };
            sendFrame(socket, response(SLOT_API_RESPONSE_TYPE.UNSUBSCRIBE_JACKPOT_POOL_RESPONSE, frame.correlation_id, unsubResponse));
            return;
        }
        default:
            sendFrame(socket, ack(frame.correlation_id, 'UNKNOWN_FRAME_TYPE', String(frame.type)));
    }
}

/** 僅供本機串接測試 */
function fakeJackpotPoolSnapshot(gameCode: string): SlotApiJackpotPoolSnapshot {
    const pools: SlotApiJackpotPoolEntry[] = (['MINI', 'MINOR', 'MAJOR', 'GRAND'] as const).map((tier) => ({
        tier,
        amount: jackpotAmount(state.jackpotPools[tier]),
    }));
    return { game_code: gameCode, currency: state.currency, pool_group_id: `${gameCode}-progressive-v1`, pools, as_of_ms: Date.now() };
}

class SlotApiMockWebSocket {
    static readonly CONNECTING = 0;
    static readonly OPEN = 1;
    static readonly CLOSING = 2;
    static readonly CLOSED = 3;

    readonly CONNECTING = 0;
    readonly OPEN = 1;
    readonly CLOSING = 2;
    readonly CLOSED = 3;

    binaryType: BinaryType = 'blob';
    bufferedAmount = 0;
    extensions = '';
    protocol = '';
    readyState = SlotApiMockWebSocket.CONNECTING;
    onopen: Listener | null = null;
    onmessage: Listener | null = null;
    onerror: Listener | null = null;
    onclose: Listener | null = null;

    private listeners: Record<string, Set<Listener>> = {};
    /** SUBSCRIBE_JACKPOT_POOL 計數 */
    jackpotPoolInterval: ReturnType<typeof setInterval> | null = null;

    constructor(public readonly url: string) {
        setTimeout(() => {
            if (this.readyState !== SlotApiMockWebSocket.CONNECTING) return;
            this.readyState = SlotApiMockWebSocket.OPEN;
            this.emit('open', { target: this });
        }, 0);
    }

    send(data: string): void {
        if (this.readyState !== SlotApiMockWebSocket.OPEN) throw new Error('websocket is not open');
        if (typeof data !== 'string') {
            sendFrame(this, ack(undefined, 'BAD_PAYLOAD', 'json text message required'));
            return;
        }

        let frame: SlotApiFrame;
        try {
            frame = JSON.parse(data) as SlotApiFrame;
        } catch {
            sendFrame(this, ack(undefined, 'BAD_PAYLOAD', 'invalid json'));
            return;
        }
        handleFrame(this, frame);
    }

    close(code: number = 1000, reason: string = ''): void {
        if (this.readyState === SlotApiMockWebSocket.CLOSED) return;
        this.readyState = SlotApiMockWebSocket.CLOSING;
        if (this.jackpotPoolInterval !== null) {
            clearInterval(this.jackpotPoolInterval);
            this.jackpotPoolInterval = null;
        }
        setTimeout(() => {
            this.readyState = SlotApiMockWebSocket.CLOSED;
            this.emit('close', { code, reason, wasClean: true, target: this });
        }, 0);
    }

    addEventListener(type: string, listener: Listener, _options?: unknown): void {
        (this.listeners[type] ??= new Set()).add(listener);
    }

    removeEventListener(type: string, listener: Listener, _options?: unknown): void {
        this.listeners[type]?.delete(listener);
    }

    dispatchEvent(event: any): boolean {
        this.emit(event.type, event);
        return true;
    }

    receive(frame: SlotApiFrame): void {
        if (this.readyState !== SlotApiMockWebSocket.OPEN) return;
        this.emit('message', { data: JSON.stringify(frame), target: this });
    }

    private emit(type: string, event: any): void {
        event.type = type;
        event.currentTarget = this;
        const handler = (this as any)[`on${type}`] as Listener | null;
        handler?.call(this, event);
        // Array.from
        for (const listener of Array.from(this.listeners[type] ?? [])) listener.call(this, event);
    }
}

function shouldUseSlotApiMock(url: unknown): boolean {
    const rawUrl = String(url);
    try {
        const base = typeof globalThis.location === 'undefined' ? 'ws://localhost' : globalThis.location.href.replace(/^http/, 'ws');
        const parsed = new URL(rawUrl, base);
        return parsed.pathname === '/ws' || parsed.pathname.endsWith('/ws');
    } catch {
        return rawUrl.includes('/ws');
    }
}

/**
 * 從目前全域的 WebSocket 找出原生的那一支
 *
 * @param current 目前全域的 WebSocket
 * @returns 原生的 WebSocket
 */
function resolveNativeWebSocket(current: any): any {
    const ctor = current?.prototype?.constructor;
    return typeof ctor === 'function' && ctor.prototype === current.prototype ? ctor : current;
}

/**
 * 建立 WebSocket 代理 `/ws` 連線接假後端 其他連線交給原生的
 *
 * @param nativeWebSocket 原生的 WebSocket
 * @returns 可以放到 `globalThis.WebSocket` 的代理建構函式
 */
function createWebSocketProxy(nativeWebSocket: any): any {
    const proxy = function (this: any, url: string | URL, protocols?: string | string[]) {
        if (shouldUseSlotApiMock(url)) return new SlotApiMockWebSocket(String(url));
        return protocols === undefined ? new nativeWebSocket(url) : new nativeWebSocket(url, protocols);
    } as any;

    proxy.prototype = nativeWebSocket.prototype;
    proxy.CONNECTING = nativeWebSocket.CONNECTING;
    proxy.OPEN = nativeWebSocket.OPEN;
    proxy.CLOSING = nativeWebSocket.CLOSING;
    proxy.CLOSED = nativeWebSocket.CLOSED;
    return proxy;
}

/**
 * 把全域的 WebSocket 換成本 bundle 的代理 看全域是不是自己的代理 不看模組旗標
 */
export function installSlotApiWebSocketMock(): void {
    const current = globalThis.WebSocket;
    if (typeof current === 'undefined' || current === webSocketProxy) return;

    NativeWebSocket ??= resolveNativeWebSocket(current);
    webSocketProxy ??= createWebSocketProxy(NativeWebSocket);
    replacedWebSocket = current;
    globalThis.WebSocket = webSocketProxy;
}

/**
 * 離開遊戲時把全域的 WebSocket 換回裝代理之前的那一支 全域已不是自己的代理就不動
 */
export function uninstallSlotApiWebSocketMock(): void {
    if (!webSocketProxy || globalThis.WebSocket !== webSocketProxy) return;
    globalThis.WebSocket = replacedWebSocket;
    replacedWebSocket = null;
}
