import { _decorator, assetManager, Component, ImageAsset, instantiate, Mask, Node, profiler, sys, UITransform, view, Widget } from 'cc';
import StoreManager from './store/StoreManager';
import { initI18n } from './i18n/i18nHelper';
import { GAMEVIEWMAP, VIEWMAP, VIEWLEVEL } from './store/StoreMap';
import AppAssetBundle from './utils/AppAssetBundle';
import AppViewPool from './ui/AppViewPool';
import EagleTracker from './tracking/EagleTracker';
import TrackerMap from './tracking/TrackerMap';
import GameConfigManager from './config/GameConfigManager';
import { isMock } from './config/GameConfig';
import { startGameMock, stopGameMock } from './net/mocks/start';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from './events/GameRuntimeEventBus';
import AppConfig from './config/AppConfig';
import { EventComponent } from './events/EventComponent';
import type { TypedEventBus } from './events/TypedEventBus';
import { PopupStack } from './ui/PopupView/PopupStack';
import { fitViewToSafeArea } from './controllers/OrientationController';
import { createRootStore, getSettingStore } from './store/RootStoreHooks';
import { NativeBundleUpdateView } from './hotupdate/NativeBundleUpdateView';
import { LoadingView } from './ui/LoadingView/LoadingView';

const { ccclass, property } = _decorator;

// 固定比例時黑邊的背景圖 放在遊戲包裡
const BACKDROP_MAIN_PATH = 'resources/Images/backdrop_main';
const BACKDROP_FREE_PATH = 'resources/Images/backdrop_free';

@ccclass('1001/GameRoot')
export class GameRoot extends EventComponent {
    /** EventComponent.subscribeEvent 是 protected，這裡提供場景初始化流程訂閱事件。 */
    public subscribeGameEvent<TEvents extends object, K extends keyof TEvents>(
        bus: TypedEventBus<TEvents>,
        type: K,
        handler: (payload: TEvents[K]) => void
    ): void {
        this.subscribeEvent(bus, type, handler);
    }

    @property(Node)
    staticNode: Node;

    @property(Node)
    gameNode: Node;

    @property(Node)
    templateNode: Node;

    @property(Node)
    middleNode: Node;

    @property(Node)
    topNode: Node;

    @property(Node)
    loadingView: Node;

    /** 落雷(symbol_up)播放時暫時搬過來的節點 不受 ReelView 的 Mask 限制 */
    @property(Node)
    symbolFxNode: Node;

    private static instance: GameRoot | null = null;

    public static getInstance(): GameRoot | null {
        return GameRoot.instance;
    }

    private static readonly TOP_LAYER = 4;

    protected override onLoad(): void {
        console.log('GameRoot onLoad');
        GameRoot.instance = this;
        // slot_game 獨立專案沒有 entry lobby 的 LoadingScene 幫忙建立 RootStore
        // 這裡自己補一次 createRootStore 內部已做過重複呼叫防呆
        createRootStore();
        this.bindShell();
        this.trackLayer(this.topNode, GameRoot.TOP_LAYER);
        PopupStack.setLayer(this.topNode);
        view.on('design-resolution-changed', this.fitContentLayers, this);
        this.fitContentLayers();
    }

    private inShell(): boolean {
        return typeof window !== 'undefined' && !!window.parent && window.parent !== window;
    }

    private postShell(type: string, payload: object = {}): void {
        if (this.inShell()) window.parent.postMessage({ source: 'game', type, payload }, '*');
    }

    /** 遊戲放在殼頁 iframe 裡時 向殼頁要初始設定 並通知殼頁載入畫面已出現 讓殼頁拿掉遮罩 */
    private bindShell(): void {
        if (!this.inShell()) return;
        window.addEventListener('message', this.onShellMessage);
        this.postShell('hi');
        // 進場選座彈窗等載入完成的 entered 才開
        this.postShell('ready', { seat: 'entered' });
    }

    // 殼頁的 hello 帶初始音樂音效 setting 是切換 套用到原本的音量設定
    private readonly onShellMessage = (event: MessageEvent): void => {
        if (event.source !== window.parent || event.data?.source !== 'host-shell') return;
        const { type, payload } = event.data;
        const settings = type === 'hello' ? payload?.settings : type === 'setting' ? payload : null;
        const store = getSettingStore();
        if (!settings || !store) return;
        if (typeof settings.music === 'boolean') store.setMusicVolumeStore(settings.music ? 1 : 0);
        if (typeof settings.sound === 'boolean') store.setSoundVolumeStore(settings.sound ? 1 : 0);
    };

    // 螢幕比設計框窄時 內容層整體縮小 整個設計框才看得到
    // 層的大小同步放大成 螢幕除以縮放 縮放後剛好蓋滿螢幕
    private fitContentLayers(): void {
        const design = view.getDesignResolutionSize();
        const visible = view.getVisibleSize();
        const scale = Math.min(1, visible.width / design.width, visible.height / design.height);
        for (const layer of [this.gameNode, this.templateNode, this.middleNode, this.topNode]) {
            if (!layer) continue;
            layer.setScale(scale, scale, 1);
            const widget = layer.getComponent(Widget);
            if (widget) widget.enabled = false;
            layer.getComponent(UITransform)?.setContentSize(visible.width / scale, visible.height / scale);
        }
        // 落雷層裁在可視範圍內
        const fx = this.symbolFxNode;
        if (fx) {
            if (!fx.getComponent(Mask)) fx.addComponent(Mask);
            fx.getComponent(UITransform)?.setContentSize(visible);
        }
        for (const templateView of this.templateNode?.children ?? []) {
            fitViewToSafeArea(templateView);
        }
    }

    public override onDestroy(): void {
        if (typeof window !== 'undefined') window.removeEventListener('message', this.onShellMessage);
        view.off('design-resolution-changed', this.fitContentLayers, this);
        if (GameRoot.instance === this) GameRoot.instance = null;
        this.removeBackdrop();
        stopGameMock();
        super.onDestroy();
    }

    // 黑邊背景圖的網址與目前模式
    private backdropEl: HTMLDivElement | null = null;
    private backdropUrls: { main: string; free: string } | null = null;
    private backdropFree = false;

    /** 載入黑邊背景圖並顯示一般背景 只有 entry 判斷為固定比例的網頁才做 沒有圖就略過 */
    private async initBackdrop(): Promise<void> {
        if (!sys.isBrowser || (globalThis as Record<string, unknown>).__subGameFixedRatio__ !== true) return;
        const bundle = assetManager.getBundle(GameConfigManager.GAMEID);
        const paths = [BACKDROP_MAIN_PATH, BACKDROP_FREE_PATH];
        if (!bundle || !paths.every((path) => bundle.getInfoWithPath(path, ImageAsset))) return;
        try {
            const [main, free] = await Promise.all(
                paths.map(
                    (path) =>
                        new Promise<string>((resolve, reject) => {
                            bundle.load(path, ImageAsset, (error, asset) => (error ? reject(error) : resolve(asset.nativeUrl)));
                        })
                )
            );
            if (!this.isValid) return;
            this.backdropUrls = { main, free };
            this.applyBackdrop();
        } catch (error) {
            console.warn('[GameRoot] 讀取黑邊背景圖失敗 略過', error);
        }
    }

    /**
     * 切換一般或免費遊戲的黑邊背景圖
     *
     * @param free 是否為免費遊戲
     */
    public setBackdropFree(free: boolean): void {
        this.backdropFree = free;
        this.applyBackdrop();
    }

    private applyBackdrop(): void {
        const urls = this.backdropUrls;
        if (!urls) return;
        if (!this.backdropEl) {
            const el = document.createElement('div');
            el.style.cssText = 'position:fixed;left:0;top:0;width:100%;height:100%;pointer-events:none;z-index:-1;background-size:cover;background-position:center;background-repeat:no-repeat';
            document.body.insertBefore(el, document.body.firstChild);
            this.backdropEl = el;
        }
        this.backdropEl.style.backgroundImage = `url("${(this.backdropFree ? urls.free : urls.main).replace(/"/g, '%22')}")`;
        // 另一張先載進快取 切換時不會閃
        new Image().src = this.backdropFree ? urls.main : urls.free;
    }

    private removeBackdrop(): void {
        this.backdropEl?.remove();
        this.backdropEl = null;
    }

    protected override start() {
        console.log('GameRoot onStart');
        // 關閉 FPS 顯示
        if (!AppConfig.DEBUG) profiler.hideStats();
        // profiler.showStats();
        void this.initBackdrop();
        this.initViewPool();
        this.registerStore();
        this.registerReactions();
        void this.initial();
    }

    private trackLayer(root: Node, layer: number): void {
        const apply = (n: Node) => {
            n.layer = layer;
            n.on(Node.EventType.CHILD_ADDED, (child: Node) => {
                this.setLayerRecursive(child, layer);
                apply(child);
            });
            for (const c of n.children) apply(c);
        };
        apply(root);
    }

    private setLayerRecursive(node: Node, layer: number): void {
        node.layer = layer;
        for (const c of node.children) this.setLayerRecursive(c, layer);
    }

    addGameNode(view) {
        if (!this.gameNode) {
            console.warn('[GameRoot] gameNode null, skip addGameNode');
            return;
        }
        this.gameNode.addChild(view);
    }

    addTemplateNode(view) {
        if (!this.templateNode) {
            console.warn('[GameRoot] templateNode null, skip addTemplateNode');
            return;
        }
        this.templateNode.addChild(view);
        this.fitContentLayers();
    }

    addMiddleNode(view) {
        if (!this.middleNode) {
            console.warn('[GameRoot] middleNode null, skip addMiddleNode');
            return;
        }
        this.middleNode.addChild(view);
    }

    addTopNode(view) {
        if (!this.topNode) {
            console.warn('[GameRoot] topNode null, skip addTopNode');
            return;
        }
        this.topNode.addChild(view);
    }

    deleteView(viewName) {
        const containers = [this.node, this.gameNode, this.templateNode, this.middleNode, this.topNode];

        let found = false;
        for (const container of containers) {
            for (let i = container.children.length - 1; i >= 0; i--) {
                if (container.children[i].name === viewName) {
                    container.children[i].destroy();
                    found = true;
                }
            }
        }

        if (!found) console.warn(`[removeView] 找不到節點: ${viewName}`);
    }

    storeManager: StoreManager;

    viewStore: any;
    viewPool: AppViewPool;
    deviceStore: any;
    templateView: Node;
    templateViewH: Node;
    bundlePath: string;

    initViewPool() {
        this.viewPool = AppViewPool.getInstance();
    }

    async initial() {
        const startTime = performance.now();

        EagleTracker.trackerEvent(TrackerMap.GAME_LOAD_START);

        if (isMock()) await startGameMock();

        console.log('------ [GameRoot] initial ------ ');

        // Native 更新由 1001 自己的 Loading 節點負責；Web 完全略過。
        if (sys.isNative) {
            const updateView = this.node.getComponentInChildren(NativeBundleUpdateView);
            if (updateView) await updateView.ensureUpdated();
            else console.warn('[GameRoot] 未掛 NativeBundleUpdateView，略過 1001 原生熱更新');
        }

        // 3.初始化 i18n
        console.log('------ [GameRoot] initial initI18n ------ ');
        await initI18n(undefined, GameConfigManager.GAMEID);

        console.log('------ [GameRoot] loadServerConfig ------ ');
        //載入 config 檔案
        await this.loadServerConfig();

        // 2.載入Bundle
        console.log('------ [GameRoot] loadBundle ------ ');
        await this.loadBundle();

        await this.syncResolutionBeforeViewInit();

        // 4.初始化 TemplateView
        console.log('------ [GameRoot] initial addTemplateView ------ ');
        await this.addTemplateView();

        // 5.連線遊戲伺服器，取得遊戲初始資料
        console.log('------ [GameRoot] initial addGamePrefab ------ ');
        await this.addGamePrefab();

        console.log('------ [GameRoot] initial connectGameServer ------ ');
        await this.connectGameServer();

        // 6.等進度條跑滿再移除 LoadingView（至少 1 秒，見 LoadingView 的 PROGRESS_MAX_SPEED）
        await this.loadingView.getComponent(LoadingView)?.fillToEnd();
        this.removeLoadingView();

        console.log('------ LOADING TIME ------ ');
        console.log('Total load time: ', performance.now() - startTime);

        // entry 的 SubGame.ts 在按下進場那一刻寫進 globalThis 的時間戳
        const enterStartTime = (globalThis as Record<string, unknown>).__subGameEnterStartTime__;
        if (typeof enterStartTime === 'number') {
            console.log('[GameRoot] 熱更新下載開始 到 遊戲出現 總耗時: ', Date.now() - enterStartTime, 'ms');
        }

        // 告訴 entry 已經進到遊戲 大廳依 existTableList 決定要不要開選座彈窗 獨立執行時沒有這個介面就跳過
        const entered = (globalThis as Record<string, unknown>).__subGameEntered__;
        if (typeof entered === 'function') entered();
        // 殼頁收到才開進場選座彈窗
        this.postShell('entered');

        EagleTracker.trackerEvent(TrackerMap.GAME_LOAD_COMPLETE, {
            total_load_time_ms: performance.now() - startTime
        });
    }

    private async syncResolutionBeforeViewInit(): Promise<void> {
        this.deviceStore.checkOrientation();

        await new Promise<void>((resolve) => {
            this.scheduleOnce(() => resolve(), 0);
        });
    }

    registerStore() {
        this.storeManager = StoreManager.getInstance();
        this.viewStore = this.storeManager.getViewStore();
        this.deviceStore = this.storeManager.getDeviceStore();
    }

    registerReactions() {
        // mobx 移除計劃：ViewStore/DeviceStore 欄位已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.VIEW_NAME_CHANGED, (e) =>
            this.addView(e.viewName)
        );

        this.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_VIEW_NAME_CHANGED, (e) =>
            this.addVGameView(e.gameViewName)
        );

        this.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DELETE_VIEW_NAME_CHANGED, (e) =>
            this.handleDeleteView(e.deleteViewName)
        );

        // 原本 fireImmediately: false，這裡不用手動呼叫一次

        this.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, (e) =>
            this.orientation(e.orientation)
        );

        // 原本 fireImmediately: false，這裡不用手動呼叫一次
    }

    orientation(orientation) {
        console.log('orientation = ', orientation);

        if (!this.templateView || !this.templateViewH) return;

        if (orientation == 'portrait') {
            this.templateView.x = 9999;
            this.templateViewH.x = 0;
            return;
        }

        this.templateView.x = 0;
        this.templateViewH.x = 9999;
    }

    async loadBundle() {
        let assetBundle = AppAssetBundle.getInstance(GameConfigManager.GAMEID);

        assetBundle.setImageRootPath('resources/Images/UI/');

        const templatePaths = [VIEWMAP.TEMPLATEVIEW.path, VIEWMAP.TEMPLATEVIEWH.path];

        await assetBundle.preloadPrefabs(
            [...templatePaths, GAMEVIEWMAP.GAMEPREFAB.path],
            this.progressCallback.bind(this)
        );

        await assetBundle.preloadImages();
    }

    async connectGameServer() {
        console.log('------ [GameRoot] connectGameServer ------ ');
        console.log('------ gameInitial ------');

        await this.storeManager.getHttpClientStore().gameInitial();

        console.log('------ gameConfig ------');

        await this.storeManager.getHttpClientStore()?.gameConfig();

        console.log('------ Server  complete ------');
    }

    async addView(viewName) {
        await this.addViewToLayer(viewName, false);
    }

    async addVGameView(viewName) {
        await this.addViewToLayer(viewName, true);
    }

    async addViewToLayer(viewName, useGameViewPool) {
        if (!viewName) return;

        // 自動找出對應的 bundle
        const coreBundle = AppAssetBundle.getInstance(GameConfigManager.GAMEID);

        const bundleName = useGameViewPool
            ? GameConfigManager.GAMEID
            : ((await coreBundle.getInfoWithPath(viewName.path)) ?? GameConfigManager.GAMEID);

        const view = await this.viewPool.getView(viewName.path, bundleName);

        switch (viewName.level) {
            case VIEWLEVEL.GAME:
                this.addGameNode(view);
                break;

            case VIEWLEVEL.TEMPLATE:
                this.addTemplateNode(view);
                break;

            case VIEWLEVEL.MIDDLE:
                this.addMiddleNode(view);
                break;

            case VIEWLEVEL.TOP:
                this.addTopNode(view);
                break;

            default:
                return;
        }
    }

    private handleDeleteView(viewName) {
        if (!viewName) return;

        this.deleteView(viewName);
        this.viewStore.setDeleteViewName('');
    }

    progressCallback(completedCount: number, totalCount: number, _item: any) {
        // console.log('completedCount = ', completedCount + 'totalCount = ' + totalCount);
        // console.log('completedCount = ', item);

        let progress = completedCount / totalCount;

        if (this.storeManager.getModel('LoadingStore')?.progress > progress) return;

        this.storeManager.getModel('LoadingStore')?.setProgress(progress);
    }

    async addTemplateView() {
        const tvHBundleId = GameConfigManager.GAMEID;
        const tvHPath: string = VIEWMAP.TEMPLATEVIEW.path;

        const tvVBundleId = GameConfigManager.GAMEID;
        const tvVPath: string = VIEWMAP.TEMPLATEVIEWH.path;

        this.templateView = instantiate(await AppAssetBundle.getInstance(tvHBundleId).loadPrefab(tvHPath));

        this.templateView.x = 9999;
        this.addTemplateNode(this.templateView);

        // 橫版是負責扣局數的 TemplateView.isPrimary
        this.isTemplateViewPrimary(this.templateView);

        this.templateViewH = instantiate(await AppAssetBundle.getInstance(tvVBundleId).loadPrefab(tvVPath));

        this.templateViewH.x = 9999;
        this.addTemplateNode(this.templateViewH);

        const isPortrait = this.deviceStore.isPortrait;

        if (isPortrait) {
            this.templateViewH.x = 0;
            return;
        }

        this.templateView.x = 0;
    }

    /**
     * 負責扣 AutoSpin 局數的TemplateView
     * 1002 是完全獨立的一份
     */
    private isTemplateViewPrimary(node: Node): void {
        const comp = node.getComponents(Component).find((c) => 'isPrimary' in c) as unknown as
            | { isPrimary: boolean }
            | undefined;

        if (comp) {
            comp.isPrimary = true;
        } else {
            console.warn('[GameRoot] isTemplateViewPrimary: 找不到帶 isPrimary 欄位的 TemplateView 元件');
        }
    }

    async addGamePrefab() {
        //先寫死，之後會改成從其他地方讀取  bundle Name
        let gamePrefab = instantiate(
            await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(GAMEVIEWMAP.GAMEPREFAB.path)
        );

        this.addGameNode(gamePrefab);
    }

    async loadServerConfig() {
        console.log('------ [GameRoot] loadServerConfig ------ ');

        let gameConfigManager = GameConfigManager.getInstance();

        await gameConfigManager.updateServerConfig();
    }

    removeLoadingView() {
        this.loadingView.destroy();
    }
}
